+async function createMcpProject(options: {
+  includeSecret?: boolean;
+} = {}): Promise<{
+  root: string;
+  configPath: string;
+  mcpPath: string;
+}> {
+  const root = await fs.mkdtemp(path.join(os.tmpdir(), "cx-doctor-mcp-"));
+  await fs.mkdir(path.join(root, "src"), { recursive: true });
+  await fs.writeFile(
+    path.join(root, "src", "index.ts"),
+    "export const value = 1;\n",
+    "utf8",
+  );
+  if (options.includeSecret === true) {
+    await fs.writeFile(
+      path.join(root, "secrets.txt"),
+      "ghp_123456789012345678901234567890123456\n",
+      "utf8",
+    );
+  }
+
+  const configPath = path.join(root, "cx.toml");
+  const mcpPath = path.join(root, "cx-mcp.toml");
+  await fs.writeFile(
+    configPath,
+    `schema_version = 1
+project_name = "demo"
+source_root = "."
+output_dir = "dist/demo-bundle"
+
+[repomix]
+style = "xml"
+show_line_numbers = false
+include_empty_directories = false
+security_check = true
+
+[files]
+include = ["src/generated/**"]
+exclude = ["node_modules/**"]
+follow_symlinks = false
+unmatched = "ignore"
+
+[sections.src]
+include = ["src/**"]
+exclude = ["src/generated/**"]
+`,
+    "utf8",
+  );
+
+  await fs.writeFile(
+    mcpPath,
+    `extends = "cx.toml"
+
+[files]
+include = ["dist/**"]
+exclude = ["tests/**"]
+`,
+    "utf8",
+  );
+  await initGitRepo(root);
+
+  return { root, configPath, mcpPath };
+}
